 function loadManage(scope,date){var u=manageEndpoint+'?scope='+encodeURIComponent(scope||'week')+'&date='+encodeURIComponent(date||requestedDate);fetch(u,{credentials:'same-origin'}).then(async function(r){var d=await r.json().catch(function(){return{ok:false,message:'Không đọc được dữ liệu quản lý.'};});if(!r.ok)throw new Error(d.message||'Bạn chưa có quyền quản lý lịch dạy thay.');return d;}).then(renderManage).catch(function(err){renderManageError(err.message||'Không tải được lịch dạy thay.');});}
