 function renderManage(data){manageData=data;if(manageSection)manageSection.remove();manageSection=document.createElement('section');manageSection.className='tkb-card p-3 mt-3 mb-3 tkb-manage-anchor';manageSection.innerHTML='<div class="d-flex justify-content-between gap-2 flex-wrap align-items-center mb-2"><div><h5 class="mb-1"><i class="bi bi-calendar-check me-1"></i> Quản lý lịch dạy thay</h5><div class="small text-muted">'+vnDate(data.from)+' – '+vnDate(data.to)+'</div></div><div class="d-flex gap-2 flex-wrap"><button class="btn btn-sm btn-outline-primary" data-scope="today">Hôm nay</button><button class="btn btn-sm btn-primary" data-scope="week">Cả tuần</button><button class="btn btn-sm btn-outline-success" id="tkbShareSubs"><i class="bi bi-share"></i> Chia sẻ ảnh</button></div></div><div class="tkb-manage-toolbar d-flex gap-2 flex-wrap align-items-center mb-2"><input type="date" class="form-control form-control-sm" id="tkbManageDate" style="max-width:170px" value="'+(requestedDate||data.from||'')+'">'+(data.can_approve?'<button class="btn btn-sm btn-success" id="tkbApproveMany"><i class="bi bi-check2-circle"></i> Duyệt đã chọn</button>':'')+(data.can_delete?'<button class="btn btn-sm btn-danger" id="tkbDeleteMany"><i class="bi bi-trash"></i> Xóa đã chọn</button>':'')+'</div><div class="table-responsive"><table class="table table-sm align-middle mb-0 tkb-manage-table"><thead><tr><th style="width:36px"><input type="checkbox" id="tkbSelectAll"></th><th>Ngày</th><th>GV nghỉ</th><th>Tiết/Lớp</th><th>GV thay</th><th>Trạng thái</th></tr></thead><tbody></tbody></table></div>';var h=manageHost();h.insertAdjacentElement('afterend',manageSection);var body=manageSection.querySelector('tbody');if(!data.rows.length)body.innerHTML='<tr><td colspan="6" class="text-center text-muted py-3">Chưa có lịch dạy thay trong phạm vi này.</td></tr>';data.rows.forEach(function(r){var s=r.status==='approved'?'Đã duyệt':(r.status==='rejected'?'Từ chối':'Chờ duyệt'),tr=document.createElemen